package com.beyondsignal.game.event;
import com.beyondsignal.game.galaxy.StarSystem; import java.util.*;
public final class ExplorationEventController{ private final ExplorationEventGenerator generator; private final ExplorationEventResolver resolver; private final ExplorationEventLog log; public ExplorationEventController(){this(new ExplorationEventGenerator(),new ExplorationEventResolver(),new ExplorationEventLog());} public ExplorationEventController(ExplorationEventGenerator g,ExplorationEventResolver r,ExplorationEventLog l){generator=Objects.requireNonNull(g);resolver=Objects.requireNonNull(r);log=Objects.requireNonNull(l);} public synchronized ExplorationEvent generate(StarSystem s,long tick,long seed){ExplorationEvent e=generator.generate(s,tick,seed);log.append(e);return e;} public synchronized ExplorationEvent resolve(String id,ExplorationChoice c,long seed){ExplorationEvent e=log.eventById(id).orElseThrow(()->new IllegalArgumentException("Unknown event: "+id)); ExplorationEvent x=resolver.resolve(e,c,seed);log.replace(x);return x;} public synchronized Optional<ExplorationEvent> latestPendingEvent(){return log.pendingEvents().stream().reduce((a,b)->b);} public ExplorationEventLog log(){return log;}}
